
// ELEMENTOS
const modal = document.getElementById("postModal");
const closeModal = document.getElementById("closeModal");
const publishButton = document.getElementById("publishButton");

const newPostButton = document.getElementById("newPostButton");
const mobileCreate = document.getElementById("mobileCreate");

const feed = document.getElementById("feed");


// ABRIR MODAL
function openModal(event) {
    if (event) event.preventDefault();
        modal.classList.add("show");
        }

        newPostButton.addEventListener("click", openModal);
        mobileCreate.addEventListener("click", openModal);


        // FECHAR MODAL
        closeModal.addEventListener("click", () => {
            modal.classList.remove("show");
            });

            modal.addEventListener("click", (event) => {
                if (event.target === modal) {
                        modal.classList.remove("show");
                            }
                            });


                            // CURTIR PUBLICAÇÃO
                            document.addEventListener("click", (event) => {

                                const button = event.target.closest(".like-button");

                                    if (!button) return;

                                        button.classList.toggle("liked");

                                            button.textContent = button.classList.contains("liked")
                                                    ? "♥"
                                                            : "♡";

                                                                const post = button.closest(".post");
                                                                    const likes = post.querySelector(".likes");

                                                                        let total = Number(
                                                                                likes.dataset.count ||
                                                                                        likes.textContent.replace(/\D/g, "")
                                                                                            );

                                                                                                if (button.classList.contains("liked")) {
                                                                                                        total++;
                                                                                                            } else {
                                                                                                                    total--;
                                                                                                                        }

                                                                                                                            likes.dataset.count = total;
                                                                                                                                likes.textContent = total.toLocaleString("pt-BR") + " curtidas";
                                                                                                                                });


                                                                                                                                // SALVAR PUBLICAÇÃO
                                                                                                                                document.addEventListener("click", (event) => {

                                                                                                                                    const button = event.target.closest(".save-button");

                                                                                                                                        if (!button) return;

                                                                                                                                            button.classList.toggle("saved");

                                                                                                                                                button.textContent = button.classList.contains("saved")
                                                                                                                                                        ? "▣"
                                                                                                                                                                : "♧";

                                                                                                                                                                });


                                                                                                                                                                // PUBLICAR
                                                                                                                                                                publishButton.addEventListener("click", () => {

                                                                                                                                                                    const caption = document.getElementById("caption").value.trim();
                                                                                                                                                                        const imageUrl = document.getElementById("imageUrl").value.trim();

                                                                                                                                                                            if (!caption && !imageUrl) {
                                                                                                                                                                                    alert("Escreva uma legenda ou informe uma imagem!");
                                                                                                                                                                                            return;
                                                                                                                                                                                                }

                                                                                                                                                                                                    const post = document.createElement("article");
                                                                                                                                                                                                        post.className = "post";

                                                                                                                                                                                                            const header = document.createElement("div");
                                                                                                                                                                                                                header.className = "post-header";

                                                                                                                                                                                                                    header.innerHTML = `
                                                                                                                                                                                                                            <img src="https://i.pravatar.cc/100?img=12"
                                                                                                                                                                                                                                         class="user-avatar">
                                                                                                                                                                                                                                                 <div class="user-info">
                                                                                                                                                                                                                                                             <strong>seu_usuario</strong>
                                                                                                                                                                                                                                                                         <small>Agora</small>
                                                                                                                                                                                                                                                                                 </div>
                                                                                                                                                                                                                                                                                         <button class="options">•••</button>
                                                                                                                                                                                                                                                                                             `;

                                                                                                                                                                                                                                                                                                 post.appendChild(header);

                                                                                                                                                                                                                                                                                                     if (imageUrl) {
                                                                                                                                                                                                                                                                                                             try {
                                                                                                                                                                                                                                                                                                                         const url = new URL(imageUrl);

                                                                                                                                                                                                                                                                                                                                     if (!["http:", "https:"].includes(url.protocol)) {
                                                                                                                                                                                                                                                                                                                                                     throw new Error("URL inválida");
                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                             const img = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                         img.src = url.href;
                                                                                                                                                                                                                                                                                                                                                                                                     img.className = "post-image";
                                                                                                                                                                                                                                                                                                                                                                                                                 img.alt = "Imagem da publicação";

                                                                                                                                                                                                                                                                                                                                                                                                                             img.onerror = () => img.remove();

                                                                                                                                                                                                                                                                                                                                                                                                                                         post.appendChild(img);

                                                                                                                                                                                                                                                                                                                                                                                                                                                 } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                             alert("Informe uma URL de imagem válida.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const content = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             content.className = "post-content";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const actions = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     actions.className = "post-actions";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         actions.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <button class="like-button">♡</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <button class="comment-button">💬</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <button>➤</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <button class="save-button">♧</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 content.appendChild(actions);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const likes = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         likes.className = "likes";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             likes.dataset.count = "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 likes.textContent = "0 curtidas";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     content.appendChild(likes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (caption) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const paragraph = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const username = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 username.textContent = "seu_usuario ";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         paragraph.append(username, document.createTextNode(caption));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 content.appendChild(paragraph);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const date = document.createElement("small");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             date.className = "date";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 date.textContent = "AGORA";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     content.appendChild(date);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         post.appendChild(content);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             feed.prepend(post);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 document.getElementById("caption").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     document.getElementById("imageUrl").value = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         modal.classList.remove("show");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // SEGUIR USUÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         document.addEventListener("click", (event) => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const button = event.target.closest(".suggestion-user button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (button.textContent === "Seguir") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             button.textContent = "Seguindo";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     button.style.color = "#8e8e8e";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 button.textContent = "Seguir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         button.style.color = "#0095f6";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // COMENTÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             document.addEventListener("click", (event) => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const button = event.target.closest(".comment-button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const comment = prompt("Escreva seu comentário:");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (!comment || !comment.trim()) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const post = button.closest(".post");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     let comments = post.querySelector(".comments-list");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!comments) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 comments = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         comments.className = "comments-list";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 post.querySelector(".post-content").appendChild(comments);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const paragraph = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const username = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 username.textContent = "seu_usuario ";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     paragraph.append(username, document.createTextNode(comment.trim()));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         comments.appendChild(paragraph);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         